import React from "react";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { INK, Bolha, CARD2, Cam, Cena, cl, COL, Fundo, FPS, GOLD, GOLD_BTN, Imagem, Item, k, lin, LINE, Ln, Metodo, MUTED, Oferta, pop, POP, Post, pulse, Roteiro, Slot } from "./kit";

// V3 — "Chega de dar desconto para encher a agenda". Voz: Roberta (ElevenLabs), 48,7 s, entra em 0,1 s;
// tempos = palavra + 0,1 s.
export const RV3_FRAMES = Math.round(50.3 * FPS);

const TOP = 300, H = 330;

// 1 · a verdade: desconto não resolve agenda vazia
const Verdade: React.FC<{ t: number }> = ({ t }) => {
  const DESC = 3.31, CAI = 4.45, TREINA = 6.1, PROMO = 8.0;
  const items: Item[] = [
    { at: 0.15, out: 3.15, el: <><Ln s="Vou falar uma" size={104} /><Ln s="*verdade*" size={150} t={t} at={0.83} /><Ln s="que ninguém quer ouvir" size={70} t={t} at={1.57} weight={600} color={MUTED} /></> },
    { at: DESC, out: 5.95, el: <><Ln s="*Desconto*" size={150} /><Ln s="não resolve" size={104} t={t} at={4.19} /><Ln s="agenda vazia." size={104} t={t} at={4.93} /></> },
    { at: TREINA, out: 99, el: <><Ln s="Ele só treina a cliente" size={84} /><Ln s="a esperar a" size={84} /><Ln s="*próxima promoção*" size={104} t={t} at={PROMO} /></> },
  ];
  const tag = pop(t, DESC, 0.4), cai = interpolate(t, [CAI, CAI + 0.9], [0, 1], { ...cl, easing: (x) => x * x });
  const bal = pop(t, PROMO + 0.1, 0.45);
  return (
    <AbsoluteFill>
      <Fundo t={t} />
      <Slot t={t} top={250} h={440} items={items} />
      {/* abertura: a lupa de "verdade" — um ponto de luz dourado que cresce atrás do texto */}
      <div style={{ position: "absolute", left: 540 - 300, top: 470 - 300, width: 600, height: 600, borderRadius: 300, background: "radial-gradient(circle, rgba(216,174,90,0.28) 0%, rgba(216,174,90,0) 70%)", opacity: k(t, 0.1, 0.5) * (1 - lin(t, 3.0, 3.3)), transform: `scale(${(0.4 + 0.6 * k(t, 0.1, 1.2) + 0.08 * Math.sin(t * 3)).toFixed(3)})` }} />
      <Cam t={t} a={0} b={9.4} kind="push">
        {t >= DESC - 0.02 && t < TREINA + 0.2 ? (
          <div style={{ position: "absolute", left: 0, right: 0, top: 860, display: "flex", justifyContent: "center", opacity: Math.min(1, tag * 2) * (1 - cai) }}>
            <div style={{ width: 460, height: 460, borderRadius: 230, backgroundImage: GOLD_BTN, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: POP, fontWeight: 800, fontSize: 190, letterSpacing: "-0.05em", color: "#140D04", boxShadow: "0 0 90px rgba(216,174,90,0.35)", transform: `translateY(${(cai * 900).toFixed(1)}px) rotate(${((1 - tag) * -40 + cai * 70).toFixed(1)}deg) scale(${(0.3 + 0.7 * tag).toFixed(3)})`, filter: `grayscale(${Math.min(1, cai * 3).toFixed(2)})` }}>-50%</div>
          </div>
        ) : null}
        {t >= TREINA ? (
          <div style={{ position: "absolute", left: 120, width: COL, top: 900, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 30 }}>
            <div style={{ opacity: Math.min(1, pop(t, TREINA + 0.1, 0.45) * 2), transform: `scale(${(0.6 + 0.4 * pop(t, TREINA + 0.1, 0.45)).toFixed(3)})`, transformOrigin: "0% 100%" }}>
              <Bolha s="Oi! Quanto tá o lash?" hora="10:02" size={48} />
            </div>
            <div style={{ alignSelf: "flex-end", opacity: Math.min(1, pop(t, 7.0, 0.45) * 2), transform: `scale(${(0.6 + 0.4 * pop(t, 7.0, 0.45)).toFixed(3)})`, transformOrigin: "100% 100%" }}>
              <Bolha s="R$ 150 😊" hora="10:05" size={48} enviado />
            </div>
            <div style={{ opacity: Math.min(1, bal * 2), transform: `scale(${(0.6 + 0.4 * bal).toFixed(3)})`, transformOrigin: "0% 100%" }}>
              <Bolha s="Me avisa na próxima promoção? 🙏" hora="10:06" size={48} />
            </div>
          </div>
        ) : null}
      </Cam>
    </AbsoluteFill>
  );
};

// 2 · a promoção relâmpago e o cansaço: trabalha mais, ganha menos
const Cansaco: React.FC<{ t: number }> = ({ t }) => {
  const A = 9.3, RAIO = 11.14, CANS = 13.96, ROWS = 16.04;
  const items: Item[] = [
    { at: 9.44, out: 13.85, el: <><Ln s="Já fez" size={104} /><Ln s="*promoção relâmpago*" size={104} t={t} at={10.5} /></> },
    { at: CANS, out: 15.9, el: <><Ln s="Você sabe como é" size={100} /><Ln s="*cansativo.*" size={140} t={t} at={14.94} /></> },
    { at: ROWS, out: 99, el: <Ln s="Você…" size={120} /> },
  ];
  const raio = pop(t, RAIO, 0.4), fl = pulse(t, RAIO, 0.35), ro = lin(t, CANS - 0.1, CANS + 0.25);
  const LINHAS: [string, string, number, "up" | "down" | "x"][] = [["trabalha", "mais", 16.26, "up"], ["ganha", "menos", 17.34, "down"], ["se sente", "desvalorizada", 19.27, "x"]];
  return (
    <AbsoluteFill>
      <Fundo t={t} x={20} y={15} />
      <Slot t={t} top={250} h={440} items={items} />
      <Cam t={t} a={A} b={20.4} kind="orbit">
        {t < CANS + 0.3 ? (
          <div style={{ position: "absolute", left: 0, right: 0, top: 880, display: "flex", justifyContent: "center", opacity: Math.min(1, raio * 2) * (1 - ro) }}>
            <div style={{ display: "flex", alignItems: "center", gap: 20, padding: "34px 56px", borderRadius: 30, backgroundImage: GOLD_BTN, fontFamily: POP, fontWeight: 800, fontSize: 64, color: "#140D04", transform: `scale(${(0.4 + 0.6 * raio + 0.08 * fl).toFixed(3)}) rotate(${(-5 + 2 * Math.sin(t * 2)).toFixed(2)}deg)`, boxShadow: `0 0 ${(60 + 120 * fl).toFixed(0)}px rgba(255,220,140,${(0.35 + 0.4 * fl).toFixed(2)})` }}>
              <svg width={54} height={66} viewBox="0 0 18 22"><path d="M11 1 L2 13 H9 L7 21 L16 9 H9 Z" fill="#140D04" /></svg>
              PROMOÇÃO RELÂMPAGO
            </div>
          </div>
        ) : null}
      </Cam>
      {/* cansaço: o relógio girando no lugar da promoção */}
      {t >= CANS && t < ROWS + 0.3 ? (
        <div style={{ position: "absolute", left: 390, top: 820, width: 300, height: 300, borderRadius: 150, border: `6px solid ${GOLD}`, opacity: k(t, CANS, 0.4) * (1 - lin(t, ROWS - 0.1, ROWS + 0.2)) }}>
          <div style={{ position: "absolute", left: 147, top: 40, width: 6, height: 112, borderRadius: 3, background: GOLD, transformOrigin: "50% 100%", transform: `rotate(${(t * 360).toFixed(1)}deg)` }} />
          <div style={{ position: "absolute", left: 146, top: 80, width: 8, height: 72, borderRadius: 4, background: INK, transformOrigin: "50% 100%", transform: `rotate(${(t * 30).toFixed(1)}deg)` }} />
        </div>
      ) : null}
      {t >= ROWS ? (
        <div style={{ position: "absolute", left: 120, width: COL, top: 760, display: "flex", flexDirection: "column", gap: 34 }}>
          {LINHAS.map(([a, b, at, kind]) => {
            const e = pop(t, at, 0.45);
            return (
              <div key={b} style={{ display: "flex", alignItems: "center", gap: 30, padding: "26px 40px", borderRadius: 34, background: CARD2, border: `1.5px solid ${LINE}`, opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * 300).toFixed(1)}px)` }}>
                <div style={{ width: 96, height: 96, borderRadius: 48, border: `3px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: POP, fontWeight: 800, fontSize: 56, color: GOLD, flexShrink: 0, transform: `translateY(${(kind === "up" ? -1 : kind === "down" ? 1 : 0) * Math.abs(Math.sin(t * 3)) * 8}px)` }}>{kind === "up" ? "↑" : kind === "down" ? "↓" : "✕"}</div>
                <div style={{ fontFamily: POP, fontWeight: 700, fontSize: kind === "x" ? 52 : 68, color: INK, letterSpacing: "-0.03em", whiteSpace: "nowrap" }}>{a} <span style={{ color: GOLD }}>{b}</span></div>
              </div>
            );
          })}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

// 3 · o que muda o jogo: um processo (responder o valor, mostrar o trabalho, follow-up leve)
const Processo: React.FC<{ t: number }> = ({ t }) => {
  const A = 20.3, S1 = 23.37, S2 = 26.17, S3 = 28.85, AGRADECE = 31.33;
  const items: Item[] = [
    { at: 20.6, out: 23.2, el: <><Ln s="O que muda o jogo" size={96} /><Ln s="é ter um *processo.*" size={104} t={t} at={22.29} /></> },
    { at: S1, out: 99, el: <Ln s="Saber como…" size={110} /> },
  ];
  const PASSOS: [string, string, string, number][] = [
    ["1", "Responder", "quando perguntam o valor", S1],
    ["2", "Mostrar seu trabalho", "sem forçar", S2],
    ["3", "Follow-up leve", "que a cliente até agradece", S3],
  ];
  return (
    <AbsoluteFill>
      <Fundo t={t} x={80} y={80} />
      <Slot t={t} top={TOP} h={H} items={items} />
      <Cam t={t} a={A} b={33.0} kind="tilt">
        {t < S1 + 0.3 ? (
          <div style={{ position: "absolute", left: 0, right: 0, top: 860, display: "flex", justifyContent: "center", gap: 26, opacity: k(t, 22.29, 0.4) * (1 - lin(t, S1 - 0.1, S1 + 0.2)) }}>
            {[0, 1, 2].map((i) => {
              const e = pop(t, 22.35 + i * 0.12, 0.45);
              return <div key={i} style={{ width: 230, height: 230, borderRadius: 40, border: `3px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: POP, fontWeight: 800, fontSize: 120, color: GOLD, transform: `scale(${(0.4 + 0.6 * e).toFixed(3)}) translateY(${(Math.sin(t * 2 + i) * 8).toFixed(1)}px)` }}>{i + 1}</div>;
            })}
          </div>
        ) : null}
        {PASSOS.map(([n, tit, sub, at], i) => {
          const nx = i < 2 ? PASSOS[i + 1][3] : 99;
          if (t < at - 0.02 || t > nx + 0.3) return null;
          const e = pop(t, at, 0.5), o = lin(t, nx - 0.1, nx + 0.2);
          return (
            <div key={n} style={{ position: "absolute", left: 120, width: COL, top: 760, padding: "50px 50px 56px", boxSizing: "border-box", borderRadius: 44, background: CARD2, border: `1.5px solid ${LINE}`, opacity: Math.min(1, e * 2) * (1 - o), transform: `translateX(${((1 - e) * 500 - o * 500).toFixed(1)}px) rotate(${((1 - e) * 6).toFixed(1)}deg)`, boxShadow: "0 40px 80px var(--shadow)" }}>
              <div style={{ width: 110, height: 110, borderRadius: 55, backgroundImage: GOLD_BTN, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: POP, fontWeight: 800, fontSize: 60, color: "#140D04" }}>{n}</div>
              <div style={{ fontFamily: POP, fontWeight: 700, fontSize: 72, color: INK, letterSpacing: "-0.03em", marginTop: 30, whiteSpace: "nowrap" }}>{tit}</div>
              <div style={{ fontFamily: POP, fontWeight: 500, fontSize: 46, color: GOLD, marginTop: 8 }}>{sub}</div>
            </div>
          );
        })}
        {t >= AGRADECE ? (
          <div style={{ position: "absolute", left: 160, top: 1260, opacity: Math.min(1, pop(t, AGRADECE, 0.45) * 2), transform: `scale(${(0.6 + 0.4 * pop(t, AGRADECE, 0.45)).toFixed(3)})`, transformOrigin: "0% 0%" }}>
            <Bolha s="Ai, obrigada por lembrar! 💛" hora="18:40" size={46} />
          </div>
        ) : null}
      </Cam>
    </AbsoluteFill>
  );
};

// 4 · tudo num método de 6 passos, com mensagens prontas e ideias de conteúdo
const Reuni: React.FC<{ t: number }> = ({ t }) => {
  const A = 32.9, SEIS = 35.24, MSG = 36.3, IDEIAS = 38.36;
  const items: Item[] = [
    { at: 33.1, out: 36.15, el: <><Ln s="Eu reuni tudo em" size={100} /><Ln s="um método de *6 passos*" size={96} t={t} at={SEIS} /></> },
    { at: MSG, out: 38.25, el: <><Ln s="mensagens prontas" size={96} /><Ln s="para o *WhatsApp*" size={96} /></> },
    { at: IDEIAS, out: 99, el: <><Ln s="e ideias de *conteúdo*" size={96} /><Ln s="para aplicar *já.*" size={96} t={t} at={40.5} /></> },
  ];
  const m = pop(t, A + 0.25, 0.6), mo = k(t, SEIS - 0.15, 0.4);
  const z = pop(t, MSG, 0.5), zo = lin(t, IDEIAS - 0.1, IDEIAS + 0.2), p = pop(t, IDEIAS, 0.5);
  return (
    <AbsoluteFill>
      <Fundo t={t} x={50} y={50} a={1.2} />
      <Slot t={t} top={TOP} h={H} items={items} />
      <Cam t={t} a={A} b={41.1} kind="float">
        {t < SEIS + 0.3 ? (
          <div style={{ position: "absolute", left: 160, top: 760, opacity: Math.min(1, m * 2) * (1 - mo), transform: `scale(${(0.6 + 0.4 * m - 0.2 * mo).toFixed(4)}) rotate(${((1 - m) * 10).toFixed(2)}deg)`, filter: mo > 0 ? `blur(${(mo * 14).toFixed(1)}px)` : undefined }}>
            <Imagem id="mockup" w={760} />
          </div>
        ) : null}
        {t >= SEIS - 0.05 && t < MSG + 0.3 ? <div style={{ opacity: 1 - lin(t, MSG - 0.1, MSG + 0.2) }}><Metodo t={t} at={SEIS} step={0.1} top={880} foco={[]} nomes={false} /></div> : null}
        {t >= MSG - 0.05 && t < IDEIAS + 0.3 ? <div style={{ position: "absolute", left: 320, top: 700, opacity: Math.min(1, z * 2) * (1 - zo), transform: `translateY(${((1 - z) * 300).toFixed(1)}px) rotate(${(4 * Math.sin(t * 1.5)).toFixed(2)}deg)` }}><Imagem id="zap" w={440} /></div> : null}
        {t >= IDEIAS - 0.05 ? <div style={{ position: "absolute", left: 220, top: 720, opacity: Math.min(1, p * 2), transform: `scale(${(0.7 + 0.3 * p).toFixed(3)})` }}><Post t={t} w={640} /></div> : null}
      </Cam>
    </AbsoluteFill>
  );
};

const CENAS: Cena[] = [
  { a: 0, tr: "push", el: (t) => <Verdade t={t} /> },
  { a: 3.31, tr: "inverte", claro: true, o: [540, 1090], el: (t) => <Verdade t={t} /> },
  { a: 9.3, tr: "slide", el: (t) => <Cansaco t={t} /> },
  { a: 16.04, tr: "inverte", claro: true, o: [540, 470], el: (t) => <Cansaco t={t} /> },
  { a: 20.35, tr: "zoom", el: (t) => <Processo t={t} /> },
  { a: 23.37, tr: "inverte", claro: true, o: [540, 1000], el: (t) => <Processo t={t} /> },
  { a: 32.95, tr: "push", el: (t) => <Reuni t={t} /> },
  { a: 41.0, tr: "flash", el: (t) => <Oferta t={t} a={41.0} preco={41.6} acesso={42.79} botao={44.5} aperta={44.9} frase="sem entregar o *seu preço.*" fraseAt={47.5} assina={48.9} /> },
];

export const RosilaneV3: React.FC = () => {
  const t = useCurrentFrame() / FPS;
  return <Roteiro t={t} cenas={CENAS} />;
};

import { loadFont as loadScript } from "@remotion/google-fonts/Allura";
import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile } from "remotion";

// Rosilane · ebook "Agenda Cheia" — peças comuns aos três anúncios (V1, V2, V3).
// Identidade da página do checkout (pay.kiwify.com.br/Bl7zjGs, vista em 11/10/2026): preto puro com dourado metálico,
// títulos em sans geométrica pesada (Poppins), a marca AGENDA CHEIA em serifa fina espaçada (Cinzel) e a assinatura
// manuscrita "Sua agenda cheia é possível" (Allura). Limpo: fundo liso, brilho dourado só no canto, texto que entra e
// fica parado no mesmo lugar; movimento contínuo só nos objetos e no fundo.

export const { fontFamily: POP } = loadPoppins("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: CIN } = loadCinzel("normal", { weights: ["400", "500", "600"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: SCRIPT } = loadScript("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

export const FPS = 30;
export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const BACK = Easing.out(Easing.back(1.5));
export const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const pulse = (t: number, a: number, d = 0.32) => interpolate(t, [a, a + 0.08, a + d], [0, 1, 0], cl);

export const BG = "#050403";
// As cores das peças são variáveis: cada cena escolhe o tema escuro (preto, como a página) ou o claro (creme do
// cartão de embarque das artes, com o dourado escurecido para dar contraste). A troca de tema é a "inversão de cor".
export const CARD = "var(--card)";
export const CARD2 = "var(--card2)";
export const LINE = "var(--line)";
export const GOLD = "var(--gold)";
export const INK = "var(--ink)";
export const GOLD_G = "linear-gradient(172deg, var(--g1) 0%, var(--g2) 28%, var(--g3) 54%, var(--g4) 76%, var(--g5) 100%)";
const tema = (o: Record<string, string>) => o as React.CSSProperties;
export const ESCURO = tema({ "--bg": "#050403", "--glow": "196,148,62", "--card": "#15120E", "--card2": "#1D1913", "--line": "rgba(216,174,90,0.34)", "--gold": "#D8AE5A", "--ink": "#FFFFFF", "--inkrgb": "255,255,255", "--ink2": "rgba(255,255,255,0.8)", "--muted": "rgba(255,255,255,0.62)", "--hair": "rgba(255,255,255,0.08)", "--dash": "rgba(255,255,255,0.18)", "--shadow": "rgba(0,0,0,0.55)", "--sent": "#3A2E16", "--tile": "rgba(30,25,18,1)", "--tag": "#F2D58E", "--g1": "#FFF1B8", "--g2": "#EBC56C", "--g3": "#B98634", "--g4": "#F2D27C", "--g5": "#9C6A20" });
export const CLARO = tema({ "--bg": "#F5ECD9", "--glow": "214,170,88", "--card": "#FFFCF4", "--card2": "#FFFBF2", "--line": "rgba(154,106,32,0.38)", "--gold": "#9A6A1E", "--ink": "#17110A", "--inkrgb": "23,17,10", "--ink2": "rgba(23,17,10,0.8)", "--muted": "rgba(23,17,10,0.58)", "--hair": "rgba(23,17,10,0.09)", "--dash": "rgba(23,17,10,0.22)", "--shadow": "rgba(110,75,20,0.2)", "--sent": "#EEDDB2", "--tile": "rgba(238,222,186,1)", "--tag": "#7A5214", "--g1": "#C99A45", "--g2": "#9E6C1F", "--g3": "#6F470E", "--g4": "#B5832F", "--g5": "#6A440C" });
export const GOLD_BTN = "linear-gradient(100deg, #F3DD9A 0%, #E2BE6A 35%, #C99A45 70%, #A9772A 100%)";
export const MUTED = "var(--muted)";
export const COL = 840; // coluna central: margem de 120 px de cada lado

export const gold: React.CSSProperties = { backgroundImage: GOLD_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" };

// "texto com *destaque*" → destaque em dourado metálico
export const Rich: React.FC<{ s: string }> = ({ s }) => (
  <>{s.split("*").map((p, j) => (j % 2 ? <span key={j} style={{ ...gold, paddingRight: "0.02em" }}>{p}</span> : <span key={j}>{p}</span>))}</>
);

// tamanho que cabe na coluna (Poppins Bold ~0,6 em por letra)
export const fit = (s: string, size: number, w = COL, f = 0.6) => Math.min(size, Math.floor(w / (s.replace(/\*/g, "").length * f)));

// ───────── fundo: preto liso com brilho dourado no canto, respirando devagar ─────────
export const Fundo: React.FC<{ t: number; x?: number; y?: number; a?: number }> = ({ t, x = 82, y = 8, a = 1 }) => (
  <AbsoluteFill style={{ background: "var(--bg)" }}>
    <AbsoluteFill style={{ background: `radial-gradient(70% 42% at ${(x + 12 * Math.sin(t * 0.8)).toFixed(2)}% ${(y + 8 * Math.cos(t * 0.65)).toFixed(2)}%, rgba(var(--glow),${(0.26 * a * (0.86 + 0.14 * Math.sin(t * 1.1))).toFixed(3)}) 0%, rgba(var(--glow),${(0.08 * a).toFixed(3)}) 45%, rgba(var(--glow),0) 100%)` }} />
  </AbsoluteFill>
);

// ───────── frases que se revezam no MESMO lugar ─────────
// Cada item ocupa o bloco fixo inteiro; o anterior some antes do próximo entrar. Linhas internas podem ter tempo
// próprio (Ln), mas o espaço delas já está reservado: nada pula nem sobe.
export type Item = { at: number; out: number; el: React.ReactNode };
export const Slot: React.FC<{ t: number; top: number; h: number; items: Item[]; gap?: number }> = ({ t, top, h, items, gap = 8 }) => (
  <>
    {items.map((it, n) =>
      t >= it.at - 0.02 && t < it.out + 0.16 ? (
