// ───────── transições entre cenas ─────────
export type Tr = "push" | "zoom" | "slide" | "iris" | "flash" | "drop" | "inverte";
export type Cena = { a: number; tr: Tr; el: (t: number) => React.ReactNode; claro?: boolean; o?: [number, number] };
const D = 0.22;
const trIn = (tr: Tr, p: number, o: [number, number] = [540, 960]): React.CSSProperties => {
  if (p >= 1) return {};
  switch (tr) {
    case "push": return { transform: `translateY(${((1 - p) * 1920).toFixed(1)}px)` };
    case "slide": return { transform: `translateX(${((1 - p) * 1080).toFixed(1)}px) rotate(${((1 - p) * 4).toFixed(2)}deg)`, transformOrigin: "50% 100%" };
    case "zoom": return { opacity: Math.min(1, p * 1.6), transform: `scale(${(1.22 - 0.22 * p).toFixed(4)})`, filter: `blur(${((1 - p) * 18).toFixed(1)}px)` };
    case "iris": return { clipPath: `circle(${(p * 2300).toFixed(0)}px at ${o[0]}px ${o[1]}px)` };
    case "inverte": return { clipPath: `circle(${(p * 2300).toFixed(0)}px at ${o[0]}px ${o[1]}px)` };
    case "flash": return { opacity: p > 0.5 ? 1 : 0 };
    case "drop": return { transform: `translateY(${(-(1 - p) * 1920).toFixed(1)}px)` };
  }
};
const trOut = (tr: Tr, p: number): React.CSSProperties => {
  if (p <= 0) return {};
  switch (tr) {
    case "push": return { transform: `translateY(${(-p * 1920).toFixed(1)}px)` };
    case "slide": return { transform: `translateX(${(-p * 1080).toFixed(1)}px) rotate(${(-p * 4).toFixed(2)}deg)`, transformOrigin: "50% 100%" };
    case "zoom": return { opacity: 1 - p, transform: `scale(${(1 - 0.1 * p).toFixed(4)})`, filter: `blur(${(p * 16).toFixed(1)}px)` };
    case "iris": return { transform: `scale(${(1 - 0.06 * p).toFixed(4)})`, filter: `brightness(${(1 - 0.6 * p).toFixed(3)})` };
    case "flash": return { opacity: p > 0.5 ? 0 : 1 };
    case "drop": return { transform: `translateY(${(p * 1920).toFixed(1)}px)` };
    case "inverte": return {};
  }
};
export const Roteiro: React.FC<{ t: number; cenas: Cena[] }> = ({ t, cenas }) => {
  const flashAt = cenas.filter((c) => c.tr === "flash").map((c) => c.a);
  const fl = Math.max(0, ...flashAt.map((a) => interpolate(t, [a - D, a, a + D * 1.6], [0, 1, 0], cl)));
  return (
    <AbsoluteFill style={{ background: BG }}>
      {cenas.map((c, i) => {
        const nx = cenas[i + 1];
        if (t < c.a - D - 0.02 || (nx && t > nx.a + D + 0.02)) return null;
        const pin = i === 0 ? 1 : interpolate(t, [c.a - D, c.a + D], [0, 1], { ...cl, easing: INOUT });
        const pout = nx ? interpolate(t, [nx.a - D, nx.a + D], [0, 1], { ...cl, easing: INOUT }) : 0;
        const si = trIn(c.tr, pin, c.o), so = nx ? trOut(nx.tr, pout) : {};
        return (
          <AbsoluteFill key={i} style={{ zIndex: i, ...(c.claro ? CLARO : ESCURO), ...so }}>
            <AbsoluteFill style={si}>{c.el(t)}</AbsoluteFill>
          </AbsoluteFill>
        );
      })}
      {cenas.map((c, i) => {
        if (c.tr !== "inverte" || t < c.a - D || t > c.a + D) return null;
        const p = interpolate(t, [c.a - D, c.a + D], [0, 1], { ...cl, easing: INOUT });
        const [x, y] = c.o ?? [540, 960], r = p * 2300;
        return <div key={`r${i}`} style={{ position: "absolute", zIndex: 98, left: x - r, top: y - r, width: 2 * r, height: 2 * r, borderRadius: r, border: `${(6 * (1 - p) + 2).toFixed(1)}px solid #D8AE5A`, boxShadow: "0 0 40px rgba(216,174,90,0.6)", opacity: 1 - p * p }} />;
      })}
      {fl > 0 ? <AbsoluteFill style={{ zIndex: 99, background: `radial-gradient(60% 45% at 50% 50%, rgba(255,236,180,${(0.9 * fl).toFixed(3)}) 0%, rgba(216,174,90,${(0.55 * fl).toFixed(3)}) 55%, rgba(120,80,20,${(0.35 * fl).toFixed(3)}) 100%)` }} /> : null}
    </AbsoluteFill>
  );
};

// câmera dos objetos (o texto não acompanha): cada cena usa uma
export type CamK = "drift" | "push" | "tilt" | "orbit" | "float";
export const Cam: React.FC<{ t: number; a: number; b: number; kind: CamK; children: React.ReactNode }> = ({ t, a, b, kind, children }) => {
  const p = lin(t, a, b);
  const tf = {
    drift: `translate(${(-60 + 120 * p).toFixed(1)}px, ${(Math.sin(t * 1.5) * 22).toFixed(1)}px) rotate(${(Math.sin(t * 0.9) * 1.2).toFixed(2)}deg)`,
    push: `scale(${(0.93 + 0.16 * p).toFixed(4)}) translateY(${(Math.sin(t * 1.4) * 16).toFixed(1)}px)`,
    tilt: `perspective(1600px) rotateY(${(-15 + 30 * p).toFixed(2)}deg) rotateX(${(5 * Math.sin(t * 1.1)).toFixed(2)}deg)`,
    orbit: `rotate(${(-4 + 8 * p).toFixed(2)}deg) scale(${(1.03 + 0.05 * Math.sin(t * 1.4)).toFixed(4)}) translateX(${(Math.sin(t * 1.1) * 24).toFixed(1)}px)`,
    float: `translateY(${(Math.sin(t * 1.8) * 30).toFixed(1)}px) scale(${(1.1 - 0.12 * p).toFixed(4)}) rotate(${(Math.sin(t * 1.2) * 1.5).toFixed(2)}deg)`,
  }[kind];
  return <AbsoluteFill style={{ transform: tf }}>{children}</AbsoluteFill>;
};

