// letras entram uma a uma a partir de `at`; `foco` = [tempo, índice] (a letra acesa e o nome dela embaixo)
export const Metodo: React.FC<{ t: number; at: number; step?: number; foco: [number, number][]; top: number; todas?: number; nomes?: boolean }> = ({ t, at, step = 0.14, foco, top, todas = 999, nomes = true }) => {
  const atual = foco.filter(([ft]) => t >= ft).pop();
  const idx = atual && t < todas ? atual[1] : -1;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top }}>
      <div style={{ display: "flex", justifyContent: "center", gap: 10 }}>
        {ETAPAS.map(([l], i) => {
          const e = pop(t, at + i * step, 0.5);
          const on = idx === i;
          const lit = atual ? (idx === -1 ? 1 : on ? 1 : 0.28) : 1;
          const fe = atual && on ? pulse(t, atual[0], 0.5) : 0;
          return (
            <div key={i} style={{ width: 128, textAlign: "center", fontFamily: POP, fontWeight: 800, fontSize: 176, lineHeight: 1, opacity: Math.min(1, e * 2) * (0.25 + 0.75 * lit), transform: `translateY(${((1 - e) * 120 + Math.sin(t * 2.4 + i) * 12).toFixed(1)}px) scale(${(0.6 + 0.4 * e + 0.1 * (on ? 1 : 0) + 0.08 * fe).toFixed(4)})`, filter: on ? "drop-shadow(0 0 28px rgba(232,190,100,0.55))" : undefined }}>
              <span style={gold}>{l}</span>
            </div>
          );
        })}
      </div>
      {nomes ? (
        <div style={{ position: "relative", height: 170, marginTop: 34 }}>
          {foco.map(([ft, i], n) => {
            const nt = n < foco.length - 1 ? foco[n + 1][0] : todas;
            if (t < ft - 0.02 || t > nt + 0.16) return null;
            const e = k(t, ft, 0.26), o = lin(t, nt - 0.02, nt + 0.12);
            return (
              <div key={n} style={{ position: "absolute", left: 120, right: 120, top: 0, textAlign: "center", opacity: Math.min(1, e * 1.5) * (1 - o), filter: `blur(${((1 - e) * 10 + o * 8).toFixed(1)}px)` }}>
                <div style={{ fontFamily: POP, fontWeight: 700, fontSize: fit(ETAPAS[i][1], 70), color: INK, letterSpacing: "-0.03em", lineHeight: 1.15 }}>{ETAPAS[i][1]}</div>
                <div style={{ fontFamily: POP, fontWeight: 500, fontSize: 38, color: MUTED, marginTop: 10 }}>{ETAPAS[i][2]}</div>
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
};

